--
-- Name: case_insensitive; Type: COLLATION; Schema: public; Owner: camac
--

CREATE COLLATION public.case_insensitive (provider = icu, deterministic = false, locale = 'und-u-ks-level2');


ALTER COLLATION public.case_insensitive OWNER TO camac;

--
-- Name: GET_INST_STATE_DESCRIPTION(character varying); Type: FUNCTION; Schema: public; Owner: camac
--

CREATE FUNCTION public."GET_INST_STATE_DESCRIPTION"(state_name character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
DESCRIPTION varchar;
BEGIN
  SELECT
  "DESCRIPTION" into DESCRIPTION
  FROM
  "INSTANCE_STATE_DESCRIPTION"
  WHERE
  "INSTANCE_STATE_ID" = "GET_INST_STATE_ID_BY_NAME"(STATE_NAME);
  RETURN DESCRIPTION;
END;
$$;


ALTER FUNCTION public."GET_INST_STATE_DESCRIPTION"(state_name character varying) OWNER TO camac;

--
-- Name: GET_INST_STATE_ID_BY_NAME(character varying); Type: FUNCTION; Schema: public; Owner: camac
--

CREATE FUNCTION public."GET_INST_STATE_ID_BY_NAME"(state_name character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
ID integer;
BEGIN
  SELECT
  "INSTANCE_STATE_ID" into ID
  FROM
  "INSTANCE_STATE"
  WHERE
  LOWER("NAME") = LOWER(STATE_NAME);
  RETURN ID;
END;
$$;


ALTER FUNCTION public."GET_INST_STATE_ID_BY_NAME"(state_name character varying) OWNER TO camac;

--
-- Name: GET_INST_STATE_NAME_BY_ID(integer); Type: FUNCTION; Schema: public; Owner: camac
--

CREATE FUNCTION public."GET_INST_STATE_NAME_BY_ID"(state_id integer) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
STATE_NAME varchar;
BEGIN
  SELECT
  "NAME" into STATE_NAME
  FROM
  "INSTANCE_STATE"
  WHERE
  "INSTANCE_STATE_ID" = STATE_ID;
  RETURN STATE_NAME;
END;
$$;


ALTER FUNCTION public."GET_INST_STATE_NAME_BY_ID"(state_id integer) OWNER TO camac;

