    "FORM_ID" integer NOT NULL,
    "GROUP_ID" integer NOT NULL,
    "INSTANCE_STATE_ID" integer NOT NULL,
    "LOCATION_ID" integer,
    "PREVIOUS_INSTANCE_STATE_ID" integer NOT NULL,
    "USER_ID" integer NOT NULL,
    case_id uuid,
    instance_group_id integer,
