--
-- Name: ech0211_document; Type: VIEW; Schema: public; Owner: camac
--

CREATE VIEW public.ech0211_document AS
 SELECT concat("ATTACHMENT_attachment_sections".attachmentsection_id, '-', "ATTACHMENT_attachment_sections".attachment_id) AS id,
    "ATTACHMENT"."ATTACHMENT_ID",
    "ATTACHMENT"."NAME",
    "ATTACHMENT"."PATH",
    "ATTACHMENT"."SIZE",
    "ATTACHMENT"."DATE",
    "ATTACHMENT"."MIME_TYPE",
    "ATTACHMENT"."IS_PARCEL_PICTURE",
    "ATTACHMENT"."DIGITAL_SIGNATURE",
    "ATTACHMENT"."IS_CONFIDENTIAL",
    "ATTACHMENT"."IDENTIFIER",
    "ATTACHMENT".group_id,
    "ATTACHMENT"."INSTANCE_ID",
    "ATTACHMENT"."SERVICE_ID",
    "ATTACHMENT"."USER_ID",
    "ATTACHMENT"."QUESTION",
    "ATTACHMENT".context,
    "ATTACHMENT".uuid,
    "ATTACHMENT_attachment_sections".attachmentsection_id
   FROM (public."ATTACHMENT_attachment_sections"
     JOIN public."ATTACHMENT" ON (("ATTACHMENT"."ATTACHMENT_ID" = "ATTACHMENT_attachment_sections".attachment_id)));


ALTER TABLE public.ech0211_document OWNER TO camac;

